head.script:
scwin.trigger1_onclick = function(e) {
	input1.addClass("req");
};

scwin.trigger2_onclick = function(e) {
	input1.addClass("req error");
};

scwin.trigger4_onclick = function(e) {
	input1.removeClass("req");
};

scwin.checkVal1 = function() {
	return (document.getElementById('input1') || document.getElementById('mf_input1')).classList.value.indexOf('w2input req error') != -1;
};
scwin.checkVal2 = function() {
	return (document.getElementById('input1') || document.getElementById('mf_input1')).classList.value.indexOf('w2input error') != -1;
};
